mapper.select:
SELECT * FROM campaign_participance_tbl
WHERE campaign_no = #{campaignNo}
LIMIT #{size} OFFSET #{page} * #{size}

mapper.update:
UPDATE campaign_participance_tbl
SET campaign_thumb = #{campaignThumb}, campaign_memo = #{campaignMemo}
WHERE campaign_participance_no = #{campaignParticipanceNo}

UPDATE member_point_tbl
SET total_point = total_point + #{pointChange}
WHERE member_id = #{memberId}

mapper.select:
SELECT campaign_title, campaign_explanation, campaign_goal_member
FROM create_campaign_tbl
WHERE campaign_no = #{campaignNo}

mapper.update:
UPDATE campaign_update_tbl
SET campaign_title = #{campaignTitle},
    campaign_explanation = #{campaignExplanation},
    campaign_goal_member = #{campaignGoalMember}
WHERE campaign_no = #{campaignNo}

UPDATE campaign_notice_tbl
SET campaign_notice_title = #{campaignNoticeTitle},
    campaign_notice_content = #{campaignNoticeContent}
WHERE campaign_notice_no = #{campaignNoticeNo}
